```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6, 0.5) p50_ms, approx_quantile(duration/1e6, 0.95) p95_ms FROM abnormal_traces WHERE (service_name='search' AND span_name='geo.Geo/Nearby') OR (service_name='geo' AND span_name='geo.Geo/Nearby') GROUP BY 1,2,3 ORDER BY 1,3",
          "claim": "search's client span to geo takes p50 ~1409ms while geo's server span stays ~0.14ms, so the delay is on the wire."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6, 0.5) p50_ms, approx_quantile(duration/1e6, 0.95) p95_ms FROM normal_traces WHERE (service_name='search' AND span_name='geo.Geo/Nearby') OR (service_name='geo' AND span_name='geo.Geo/Nearby') GROUP BY 1,2,3 ORDER BY 1,3",
          "claim": "In the normal period the same search-to-geo client span was about 0.47ms p50 and geo server about 0.13ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT approx_quantile(duration/1e6, 0.1) p10, approx_quantile(duration/1e6, 0.5) p50, approx_quantile(duration/1e6, 0.9) p90, count(*) n FROM abnormal_traces WHERE service_name='search' AND attr_span_kind='Client' AND span_name='geo.Geo/Nearby'",
          "claim": "Nearly every search-to-geo call is slow, with p10 about 1318ms, so the whole connection is delayed rather than a few outliers."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, attr_k8s_pod_name pod, min(value) mn, max(value) mx FROM abnormal_metrics_sum WHERE metric IN ('k8s.container.restarts','k8s.pod.uptime') AND service_name IN ('search','geo') GROUP BY 1,2,3",
          "claim": "Search and geo pods show no restarts and continuous uptime, so the delay is not a pod restart."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6, 0.5) p50_ms, approx_quantile(duration/1e6, 0.95) p95_ms FROM abnormal_traces WHERE (service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby')) OR (service_name='search' AND span_name='search.Search/Nearby' AND attr_span_kind='Server') GROUP BY 1,2,3 ORDER BY 1,3",
          "claim": "Search's server span is ~1413ms p50 and frontend's /hotels server span is ~2674ms p95, while frontend's own time stays near 0.5ms."
        }
      ]
    }
  ]
}
```

